const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var medina = ee.Geometry.Point([39.5692, 24.5247]); // Longitude, Latitude
  var roi = medina.buffer(20000); // 20 km buffer to cover urban area

  // Date ranges
  var date1984 = ['1984-06-01', '1984-06-30'];
  var date2018 = ['2018-07-01', '2018-07-31'];

  // 2. Data Acquisition Functions
  // Function to mask clouds and shadows for Landsat 5
  function maskCloudsL5(image) {
    var qa = image.select('QA_PIXEL');
    var cloudMask = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4)); // Cloud and cloud shadow
    return image.updateMask(cloudMask.not());
  }

  // Function to mask clouds and shadows for Landsat 8
  function maskCloudsL8(image) {
    var qa = image.select('QA_PIXEL');
    var cloudMask = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4));
    return image.updateMask(cloudMask.not());
  }

  // Get Landsat 5 composite for 1984
  var col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterDate(date1984[0], date1984[1])
    .filterBounds(roi)
    .map(maskCloudsL5);

  // Check if collection is empty, try widening date range
  if (col1984.size().getInfo() === 0) {
    col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterDate('1984-05-01', '1984-07-31')
      .filterBounds(roi)
      .map(maskCloudsL5);
  }

  // Get Landsat 8 composite for 2018
  var col2018 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(date2018[0], date2018[1])
    .filterBounds(roi)
    .map(maskCloudsL8);

  if (col2018.size().getInfo() === 0) {
    col2018 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate('2018-06-01', '2018-08-31')
      .filterBounds(roi)
      .map(maskCloudsL8);
  }

  // Check for empty collections
  var size1984 = col1984.size().getInfo();
  var size2018 = col2018.size().getInfo();
  print('1984 Images:', size1984);
  print('2018 Images:', size2018);

  if (size1984 === 0 || size2018 === 0) {
    print('<answer>C1</answer>');
    return;
  }

  // Create median composites
  var comp1984 = col1984.median();
  var comp2018 = col2018.median();

  // 3. Compute NDBI (Normalized Difference Built-up Index)
  // For Landsat 5: SWIR = band 5, NIR = band 4
  var ndbi1984 = comp1984.normalizedDifference(['SR_B5', 'SR_B4']).rename('ndbi');
  // For Landsat 8: SWIR = band 6, NIR = band 5
  var ndbi2018 = comp2018.normalizedDifference(['SR_B6', 'SR_B5']).rename('ndbi');

  // Threshold NDBI > 0 to get built-up pixels
  var builtUp1984 = ndbi1984.gt(0).selfMask();
  var builtUp2018 = ndbi2018.gt(0).selfMask();

  // 4. Count built-up pixels in the ROI
  var count1984 = builtUp1984.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).get('ndbi').getInfo();

  var count2018 = builtUp2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).get('ndbi').getInfo();

  // Check for no valid pixels
  if (count1984 === 0 || count2018 === 0) {
    print('1984 Built-up Pixels:', count1984);
    print('2018 Built-up Pixels:', count2018);
    print('<answer>C2</answer>');
    return;
  }

  // Compute area in km² (pixel area = 30m × 30m = 900 m² = 0.0009 km²)
  var area1984 = count1984 * 0.0009;
  var area2018 = count2018 * 0.0009;

  print('1984 Built-up Area (km²):', area1984.toFixed(2));
  print('2018 Built-up Area (km²):', area2018.toFixed(2));

  // 5. Validation & Final Answer
  // Check for invalid results
  if (area1984 === null || area2018 === null || 
      isNaN(area1984) || isNaN(area2018) || 
      area1984 < 0 || area2018 < 0) {
    print('<answer>C3</answer>');
    return;
  }

  // Determine if urban area expanded (with 5% threshold to account for noise)
  if (area2018 > area1984 * 1.05) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
